<?php if(!defined('SW_APP')){http_response_code(404);exit;}$rows=all("SELECT r.id,r.title,r.finalized_at AS closed_at,w.winning_number AS ticket_number,w.claim_status,e.sha256 AS archive_sha256,e.published_at,p.name FROM raffles r LEFT JOIN winners w ON w.raffle_id=r.id LEFT JOIN raffle_evidence e ON e.raffle_id=r.id LEFT JOIN participants p ON p.id=w.participant_id AND p.raffle_id=w.raffle_id AND p.number=w.winning_number WHERE r.status='finalizado' ORDER BY r.finalized_at DESC,r.id DESC");?>
<div class="page-heading"><p class="eyebrow">RESULTADOS</p><h1>Ganadores</h1><p>Consulta el resultado de los sorteos finalizados.</p></div><section class="panel"><div class="section-heading"><h2>Resultados y premios</h2><p>El ganador se revelará mediante el archivo ZIP protegido con el PDF original. La publicación y verificación aún no están habilitadas.</p></div><?php if(!$rows):empty_state('No hay sorteos finalizados','Cuando cierres un sorteo, aparecerá en esta sección.');else:?><div class="table-wrap"><table><thead><tr><th>Sorteo</th><th>Fecha de cierre</th><th>Boleto ganador</th><th>Ganador</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['title'])?></td><td><?=h($r['closed_at']??'—')?></td><td><?=h($r['ticket_number']??'—')?></td><td><?=h($r['name']??'—')?></td><td><?=$r['ticket_number']===null?'<span class="status pendiente">Sin revelar</span>':h($r['claim_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
